package local.proskurnin.preview;
import java.io.*;import java.net.*;import java.util.*;import org.xmlpull.v1.*;
final class RatesClient {
 static double positive(double v)throws IOException{if(Double.isNaN(v)||Double.isInfinite(v)||v<=0)throw new IOException("Invalid rate");return v;}
 static String[] cbr()throws Exception{return cbr("");}
 static String[] cbr(String suffix)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://www.cbr.ru/scripts/XML_daily.asp"+suffix).openConnection();try{c.setConnectTimeout(4500);c.setReadTimeout(4500);if(c.getResponseCode()!=200)throw new IOException("HTTP");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[2048];int n;long end=System.nanoTime()+6000000000L;while((n=in.read(b))!=-1){if(out.size()+n>131072||System.nanoTime()>end)throw new IOException("Limit");out.write(b,0,n);}}return parse(out.toByteArray());}finally{c.disconnect();}}
 static String[] fiat()throws Exception{try{String[] r=cbr();return new String[]{r[0],r[1],r[2],"ЦБ · "+r[3]};}catch(Exception unavailable){org.json.JSONObject r=WeatherClient.json("https://api.coinbase.com/v2/exchange-rates?currency=RUB").getJSONObject("data").getJSONObject("rates");return new String[]{String.valueOf(1/positive(r.getDouble("USD"))),String.valueOf(1/positive(r.getDouble("EUR"))),String.valueOf(1/positive(r.getDouble("CNY"))),"Coinbase · справочно"};}}
 static String[] parse(byte[] xml)throws Exception{XmlPullParser p=android.util.Xml.newPullParser();p.setInput(new ByteArrayInputStream(xml),null);String[] result=new String[4];String code="",value="",nominal="";for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("ValCurs"))result[3]=p.getAttributeValue(null,"Date");else if(tag.equals("Valute")){code=value=nominal="";}else if(tag.equals("CharCode"))code=p.nextText();else if(tag.equals("Value"))value=p.nextText();else if(tag.equals("Nominal"))nominal=p.nextText();}else if(event==XmlPullParser.END_TAG&&p.getName().equals("Valute")){int idx=Arrays.asList("USD","EUR","CNY").indexOf(code);if(idx>=0)result[idx]=String.valueOf(positive(Double.parseDouble(value.replace(',','.')))/positive(Double.parseDouble(nominal)));}}for(String v:result)if(v==null)throw new IOException("Missing rate");return result;}
 static double bitcoin()throws Exception{return positive(WeatherClient.json("https://api.coinbase.com/v2/exchange-rates?currency=BTC").getJSONObject("data").getJSONObject("rates").getDouble("USD"));}
 static double previous(String code,boolean cbr,String day)throws Exception{if(cbr){String[] d=day.split("-");String[] values=cbr("?date_req="+d[2]+"/"+d[1]+"/"+d[0]);return positive(Double.parseDouble(values[Arrays.asList("USD","EUR","CNY").indexOf(code)]));}String currency=code.equals("BTC")?"USD":"RUB";org.json.JSONObject data=WeatherClient.json("https://api.coinbase.com/v2/prices/"+code+"-"+currency+"/spot?date="+day).getJSONObject("data");if(!currency.equals(data.getString("currency"))||!code.equals(data.getString("base")))throw new IOException("Wrong pair");return positive(data.getDouble("amount"));}
}
